require 'minitest/autorun'

class UserRegistrationTest < Minitest::Test
  def test_user_registration_alpha
    result = 0
    result += 1
    result += 2
    result += 3
    result += 4
    result += 5
    assert_equal 15, result
  end

  def test_user_registration_beta
    result = 0
